import{_ as r,a0 as s,w as i,s as l,I as o,x as a,a1 as n,A as p,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat","title":"如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址","tag":"201504","desc":""},"relativePath":"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat.md","filePath":"[post].md"}'),d={name:"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat.md"};function c(h,t,u,v,T,P){const e=s("Link");return i(),l("div",null,[t[20]||(t[20]=o("h1",{id:"如何在-centos-rhel-中为-apache-tomcat-绑定-ipv4-地址",tabindex:"-1"},[a("如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址 "),o("a",{class:"header-anchor",href:"#如何在-centos-rhel-中为-apache-tomcat-绑定-ipv4-地址","aria-label":"Permalink to “如何在 CentOS/RHEL 中为 Apache Tomcat 绑定 IPv4 地址”"},"​")],-1)),t[21]||(t[21]=o("p",null,"今天我们来学习一下如何在CentOS 7 Linux分布式系统中为Tomcat绑定IPv4。",-1)),o("p",null,[t[1]||(t[1]=o("strong",null,"Apache Tomcat",-1)),t[2]||(t[2]=a(" 是由",-1)),n(e,{href:"http://www.apache.org/"},{default:p(()=>[...t[0]||(t[0]=[a("Apache 软件基金会",-1)])]),_:1}),t[3]||(t[3]=a(" 开发的开源web服务器和servlet容器。它实现了Java Servlet，JavaServer页面（JSP），Java的统一表达式语言，以及Sun Microsystems的Java的WebSocket规范，并提供了一个运行java代码的web服务器环境。",-1))]),t[22]||(t[22]=o("p",null,"如果由于tomcat默认绑定到IPv6而导致我们的web服务器不能正常工作，就有必要将tomcat绑定到IPv4。众所周知，IPv6是为设备分配IP地址的现代方法，虽然在不久的将来也许会得到应用，但是现在并没有得到完全应用。由于没有用处，目前我们并不需要将我们的Tomcat服务器向IPv6转换，我们应该将其绑定到IPv4。",-1)),o("p",null,[t[5]||(t[5]=a("在开始将tomcat绑定到IPv4之前，我们应该确保在我们的CentOS 7中已经安装了tomcat。可以看这个",-1)),n(e,{href:"http://linoxide.com/linux-how-to/install-tomcat-8-centos-7/"},{default:p(()=>[...t[4]||(t[4]=[a("如何在CentOS 7.0服务器中安装tomcat 8",-1)])]),_:1}),t[6]||(t[6]=a("的指导。",-1))]),t[23]||(t[23]=m(`<h3 id="_1-切换到tomcat用户" tabindex="-1">1. 切换到tomcat用户 <a class="header-anchor" href="#_1-切换到tomcat用户" aria-label="Permalink to “1. 切换到tomcat用户”">​</a></h3><p>首先，我们要切换到 <strong>tomcat</strong> 用户。我们可以通过在shell或者终端中运行 <strong>su tomcat</strong> 命令完成。</p><pre><code># su tomcat
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/switch-user-tomcat.png" alt="切换到tomcat用户"></p><h3 id="_2-找到文件-catalina-sh" tabindex="-1">2. 找到文件 Catalina.sh <a class="header-anchor" href="#_2-找到文件-catalina-sh" aria-label="Permalink to “2. 找到文件 Catalina.sh”">​</a></h3><p>现在我们要进入Apache Tomcat安装目录下的bin文件夹，通常是 <strong>/usr/share/apache-tomcat-8.0.x/bin/</strong>， 这里的x是 Apache Tomcat发行版的子版本号。因为我的CentOS 7服务器中安装的版本是8.0.18，这里我的目录是 <strong>/usr/share/apache-tomcat-8.0.18/bin/</strong>。</p><pre><code>$ cd /usr/share/apache-tomcat-8.0.18/bin
</code></pre><p><strong>注意：请用你系统中安装的Apache Tomcat的版本号替换8.0.18。</strong></p><p>在bin目录中，有一个名字是catalina.sh的脚本文件。这就是我们要编辑的文件，我们将在里面增加一行将tomcat绑定到IPv4的配置信息。你可以通过在shell或者终端中运行命令 <strong>ls</strong> 来查看这个文件。</p><pre><code>$ ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/finding-catalina.sh_.png" alt="查找文件 catalina.sh"></p><h3 id="_3-配置-catalina-sh" tabindex="-1">3. 配置 Catalina.sh <a class="header-anchor" href="#_3-配置-catalina-sh" aria-label="Permalink to “3. 配置 Catalina.sh”">​</a></h3><p>如图所示，我们将在catalina.sh脚本文件的最后增加一行 <code>JAVA_OPTS= &quot;$JAVA_OPTS -Djava.net.preferIPv4Stack=true -Djava.net.preferIPv4Addresses&quot;</code>。我们可以使用我们喜欢的文本编辑器来编辑这个文件，例如nano、vim等等。这里我们使用nano。</p><pre><code>$ nano catalina.sh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/catalina-script.png" alt="Catalina script"></p><p>然后，如下图所示，将该行增加到文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configured-catalina.png" alt="配置 catalina"></p><p>现在，我们已经将配置信息增加到文件中。保存文件并退出nano。</p><h3 id="_4-重启" tabindex="-1">4. 重启 <a class="header-anchor" href="#_4-重启" aria-label="Permalink to “4. 重启”">​</a></h3><p>现在，我们通过重启tomcat服务器使配置生效。我们要先运行shutdown.sh，然后运行startup.sh。</p><pre><code>$ ./shutdown.sh
</code></pre><p>运行可执行文件startup.sh:</p><pre><code>$ ./startup.sh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/restarting-tomcat-server.png" alt="重启apache tomcat 服务器"></p><p>这将重启我们的tomcat服务器并加载将服务器绑定到IPv4的配置信息。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>好了，我们终于将我们运行在CentOS 7 Linux发行版上的tomcat服务器绑定到IPv4上了。尽管IPv6在不久的将来也许会得到应用，但由于现在还没有使用，如果因为将你的Tomcat服务器绑定到IPv6上而使得你的tomcat服务器不工作，就有必要将tomcat绑定到IPv4上，这也很简单。如果你有任何疑问，建议，反馈，请在下面的评论框中写下来，让我们知道有什么需要增加或者改进。非常感谢！</p><hr>`,28)),o("p",null,[t[8]||(t[8]=a("via: ",-1)),n(e,{href:"http://linoxide.com/linux-how-to/bind-apache-tomcat-ipv4-centos/"},{default:p(()=>[...t[7]||(t[7]=[a("http://linoxide.com/linux-how-to/bind-apache-tomcat-ipv4-centos/",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=a("作者：",-1)),n(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...t[9]||(t[9]=[a("Arun Pyasi",-1)])]),_:1}),t[13]||(t[13]=a(" 译者：",-1)),n(e,{href:"https://github.com/ictlyh"},{default:p(()=>[...t[10]||(t[10]=[a("ictlyh",-1)])]),_:1}),t[14]||(t[14]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[a("Linux中国",-1)])]),_:1}),t[19]||(t[19]=a(" 荣誉推出",-1))])])}const x=r(d,[["render",c]]);export{f as __pageData,x as default};
